content.content:
1	import AppKit
2	
3	/// The product's door to the tutorials (spec §11 TU-10): Help ▸ Tutorials
4	/// starts one in the front project window through the runner, and the coach
5	/// shows it — the coach panel beside the window it serves and the spotlight
6	/// over it. A start that cannot run (no project window, unmet `needs`, a
7	/// tutorial the model refuses) is an OFFER in the panel: what is missing and
8	/// Open Practice Project, which opens the copy and starts the tutorial
9	/// there. Never an alert, a sheet or a modal run.
10	///
11	/// **One tutorial at a time.** The coach serves the window whose runner last
12	/// posted `.tutorialRunnerDidChange` as current; a start in another window —
13	/// a dev tool's included — exits the served window's runner first. Closing
14	/// the served window (or its project) ends its tutorial; moving or resizing
15	/// it re-places the panel; minimising it hides the panel and the ring.
16	///
17	/// Views over the runner (TU-8, TU-9): the panel and the ring read its state
18	/// and the buttons call its moves; no wait, reveal or Show Me logic lives
19	/// here. Main only. It holds the editor and runners weakly and has no
20	/// `deinit` work; its observers are block-based and `[weak self]`.
21	final class TutorialCoach {
22	    static let shared = TutorialCoach()
23	    static let noWindowSentence = "This tutorial runs in a project window."
24	    static let offerLine =
25	        "Open the practice project, or open a movie of your own (File ▸ Open…)."
26	    /// The panel's distance from the editor window beside it, and its inset
27	    /// inside the window's corner when neither side fits.
28	    private static let besideGap: CGFloat = 12
29	    private static let cornerInset: CGFloat = 16
30	
31	    private(set) weak var editor: EditorViewController?
32	    private(set) var panel: TutorialPanelController?
33	    let spotlight = TutorialSpotlight()
34	
35	    private var observing = false
36	    private var windowObservers: [NSObjectProtocol] = []
37	    /// The tutorial an offer is for, and the editor it sits beside.
38	    private var offer: (id: String, title: String)?
39	    private weak var offerEditor: EditorViewController?
40	    /// The runner, step and finish the ring last showed, so a new step
41	    /// brings its target into view once.
42	    private var lastStep: (runner: ObjectIdentifier, index: Int, finished: Bool)?
43	
44	    private init() {}
45	
46	    /// Registers the runner observer once (from `tutorialsMenu()`).
47	    func observe() {
48	        guard !observing else { return }
49	        observing = true
50	        _ = NotificationCenter.default.addObserver(
51	            forName: .tutorialRunnerDidChange, object: nil, queue: nil
52	        ) { [weak self] note in
53	            guard let runner = note.object as? TutorialRunner else { return }
54	            self?.runnerChanged(runner)
55	        }
56	    }
57	
58	    // MARK: - Starting
59	
60	    /// Help ▸ Tutorials ▸ <page> ▸ <tutorial>.
61	    func start(id: String) {
62	        observe()
63	        let library: TutorialLibrary
64	        do {
65	            library = try TutorialLibrary.bundled()
66	        } catch {
67	            showOffer(id: id, title: "Tutorial", sentence: error.localizedDescription, beside: nil)
68	            return
69	        }
70	        guard let tutorial = library.tutorial(id: id) else {
71	            let sentence = library.refused[id].map { "The tutorial \(id) does not read: \($0)." }
72	                ?? "No tutorial is called \(id)."
73	            showOffer(id: id, title: "Tutorial", sentence: sentence, beside: Self.frontEditor())
74	            return
75	        }
76	        let title = Self.displayTitle(tutorial.title)
77	        guard let editor = Self.frontEditor() else {
78	            showOffer(id: id, title: title, sentence: Self.noWindowSentence, beside: nil)
79	            return
80	        }
81	        do {
82	            offer = nil
83	            try TutorialRunner.start(tutorial, in: editor)
84	        } catch let refusal as TutorialRefusal {
85	            showOffer(id: id, title: title, sentence: refusal.sentence, beside: editor)
86	        } catch {
87	            showOffer(id: id, title: title, sentence: error.localizedDescription, beside: editor)
88	        }
89	    }
90	
91	    /// A panel button.
92	    func press(_ b: TutorialPanelButton) {
93	        switch b {
94	        case .openPractice:
95	            openPractice()
96	            return
97	        case .close:
98	            offer = nil
99	            render()
100	            return
101	        default:
102	            break
103	        }
104	        guard let runner = editor?.tutorialRunner else { return }
105	        do {
106	            switch b {
107	            case .back: try runner.back()
108	            case .showMe: try runner.showMe()
109	            case .skip: try runner.skip()
110	            case .next: try runner.next()
111	            default: runner.exit()
112	            }
113	        } catch {
114	            NSSound.beep()
115	        }
116	    }
117	
118	    /// Opens the practice copy and starts the offered tutorial in it; a
119	    /// failure stays in the offer as its message.
120	    private func openPractice() {
121	        guard let pending = offer else { return }
122	        let sentence = (panel?.state()["text"] as? String) ?? ""
123	        do {
124	            let document = try PracticeProject.open()
125	            let opened = document.windowControllers
126	                .compactMap { $0.contentViewController as? EditorViewController }.first
127	            guard let opened, let tutorial = try TutorialLibrary.bundled().tutorial(id: pending.id)
128	            else {
129	                offer = nil
130	                render()
131	                return
132	            }
133	            offer = nil
134	            try TutorialRunner.start(tutorial, in: opened)
135	        } catch let refusal as TutorialRefusal {
136	            showOffer(
137	                id: pending.id, title: pending.title, sentence: sentence, beside: offerEditor,
138	                message: refusal.sentence)
139	        } catch {
140	            showOffer(
141	                id: pending.id, title: pending.title, sentence: sentence, beside: offerEditor,
142	                message: error.localizedDescription)
143	        }
144	    }
145	
146	    private func showOffer(
147	        id: String, title: String, sentence: String, beside: EditorViewController?,
148	        message: String? = nil
149	    ) {
150	        offer = (id, title)
151	        offerEditor = beside
152	        spotlight.hide()
153	        let panel = ensurePanel()
154	        panel.showOffer(
155	            title: title, sentence: sentence, message: message ?? Self.offerLine, tutorial: id)
156	        place(beside: beside)
157	        panel.window?.orderFront(nil)
158	    }
159	
160	    // MARK: - Serving
161	
162	    private func runnerChanged(_ runner: TutorialRunner) {
163	        guard let changed = runner.editor else { return }
164	        if changed !== editor {
165	            // A stale runner of another window (an exit there) changes nothing.
166	            guard changed.tutorialRunner === runner else { return }
167	            let previous = editor
168	            serve(changed)
169	            previous?.tutorialRunner?.exit()
170	        }
171	        if changed.tutorialRunner === runner { offer = nil }
172	        render()
173	    }
174	
175	    /// The served window's step in the panel and its target in the ring, or
176	    /// both hidden once no tutorial runs there.
177	    private func render() {
178	        if offer != nil { return }
179	        guard let editor, let runner = editor.tutorialRunner,
180	              let window = editor.view.window, !window.isMiniaturized
181	        else {
182	            hideAll()
183	            if editor?.tutorialRunner == nil { unserve() }
184	            return
185	        }
186	        let panel = ensurePanel()
187	        panel.showStep(runner)
188	        place(beside: editor)
189	        panel.window?.orderFront(nil)
190	        let step = (
191	            runner: ObjectIdentifier(runner), index: runner.index, finished: runner.finished
192	        )
193	        let changed = lastStep.map { $0 != step } ?? true
194	        lastStep = step
195	        spotlight.show(
196	            runner.finished ? nil : runner.currentStep.spotlight, in: editor,
197	            created: runner.created, stepChanged: changed)
198	    }
199	
200	    private func hideAll() {
201	        panel?.window?.orderOut(nil)
202	        spotlight.hide()
203	        lastStep = nil
204	    }
205	
206	    private func serve(_ next: EditorViewController) {
207	        unserve()
208	        editor = next
209	        guard let window = next.view.window else { return }
210	        let center = NotificationCenter.default
211	        windowObservers.append(
212	            center.addObserver(
213	                forName: NSWindow.willCloseNotification, object: window, queue: nil
214	            ) { [weak self] _ in self?.servedWindowWillClose() })
215	        for name in [NSWindow.didMoveNotification, NSWindow.didResizeNotification] {
216	            windowObservers.append(
217	                center.addObserver(forName: name, object: window, queue: nil) { [weak self] _ in
218	                    guard let self, self.panel?.window?.isVisible == true else { return }
219	                    self.place(beside: self.offer == nil ? self.editor : self.offerEditor)
220	                })
221	        }
222	        for name in [NSWindow.didMiniaturizeNotification, NSWindow.didDeminiaturizeNotification] {
223	            windowObservers.append(
224	                center.addObserver(forName: name, object: window, queue: nil) { [weak self] _ in
225	                    self?.render()
226	                })
227	        }
228	    }
229	
230	    private func unserve() {
