import AppKit

/// The product's door to the tutorials (spec §11 TU-10): Help ▸ Tutorials
/// starts one in the front project window through the runner, and the coach
/// shows it — the coach panel beside the window it serves and the spotlight
/// over it. A start that cannot run (no project window, unmet `needs`, a
/// tutorial the model refuses) is an OFFER in the panel: what is missing and
/// Open Practice Project, which opens the copy and starts the tutorial
/// there. Never an alert, a sheet or a modal run.
///
/// **One tutorial at a time.** The coach serves the window whose runner last
/// posted `.tutorialRunnerDidChange` as current; a start in another window —
/// a dev tool's included — exits the served window's runner first. Closing
/// the served window (or its project) ends its tutorial; moving or resizing
/// it re-places the panel; minimising it hides the panel and the ring.
///
/// Views over the runner (TU-8, TU-9): the panel and the ring read its state
/// and the buttons call its moves; no wait, reveal or Show Me logic lives
/// here. Main only. It holds the editor and runners weakly and has no
/// `deinit` work; its observers are block-based and `[weak self]`.
final class TutorialCoach {
    static let shared = TutorialCoach()
    static let noWindowSentence = "This tutorial runs in a project window."
    static let offerLine =
        "Open the practice project, or open a movie of your own (File ▸ Open…)."
    /// The panel's distance from the editor window beside it, and its inset
    /// inside the window's corner when neither side fits.
    private static let besideGap: CGFloat = 12
    private static let cornerInset: CGFloat = 16

    private(set) weak var editor: EditorViewController?
    private(set) var panel: TutorialPanelController?
    let spotlight = TutorialSpotlight()

    private var observing = false
    private var windowObservers: [NSObjectProtocol] = []
    /// The tutorial an offer is for, and the editor it sits beside.
    private var offer: (id: String, title: String)?
    private weak var offerEditor: EditorViewController?
    /// The runner, step and finish the ring last showed, so a new step
    /// brings its target into view once.
    private var lastStep: (runner: ObjectIdentifier, index: Int, finished: Bool)?

    private init() {}

    /// Registers the runner observer once (from `tutorialsMenu()`).
    func observe() {
        guard !observing else { return }
        observing = true
        _ = NotificationCenter.default.addObserver(
            forName: .tutorialRunnerDidChange, object: nil, queue: nil
        ) { [weak self] note in
            guard let runner = note.object as? TutorialRunner else { return }
            self?.runnerChanged(runner)
        }
    }

    // MARK: - Starting

    /// Help ▸ Tutorials ▸ <page> ▸ <tutorial>.
    func start(id: String) {
        observe()
        let library: TutorialLibrary
        do {
            library = try TutorialLibrary.bundled()
        } catch {
            showOffer(id: id, title: "Tutorial", sentence: error.localizedDescription, beside: nil)
            return
        }
        guard let tutorial = library.tutorial(id: id) else {
            let sentence = library.refused[id].map { "The tutorial \(id) does not read: \($0)." }
                ?? "No tutorial is called \(id)."
            showOffer(id: id, title: "Tutorial", sentence: sentence, beside: Self.frontEditor())
            return
        }
        let title = Self.displayTitle(tutorial.title)
        guard let editor = Self.frontEditor() else {
            showOffer(id: id, title: title, sentence: Self.noWindowSentence, beside: nil)
            return
        }
        do {
            offer = nil
            try TutorialRunner.start(tutorial, in: editor)
        } catch let refusal as TutorialRefusal {
            showOffer(id: id, title: title, sentence: refusal.sentence, beside: editor)
        } catch {
            showOffer(id: id, title: title, sentence: error.localizedDescription, beside: editor)
        }
    }

    /// A panel button.
    func press(_ b: TutorialPanelButton) {
        switch b {
        case .openPractice:
            openPractice()
            return
        case .close:
            offer = nil
            render()
            return
        default:
            break
        }
        guard let runner = editor?.tutorialRunner else { return }
        do {
            switch b {
            case .back: try runner.back()
            case .showMe: try runner.showMe()
            case .skip: try runner.skip()
            case .next: try runner.next()
            default: runner.exit()
            }
        } catch {
            NSSound.beep()
        }
    }

    /// Opens the practice copy and starts the offered tutorial in it; a
    /// failure stays in the offer as its message.
    private func openPractice() {
        guard let pending = offer else { return }
        let sentence = (panel?.state()["text"] as? String) ?? ""
        do {
            let document = try PracticeProject.open()
            let opened = document.windowControllers
                .compactMap { $0.contentViewController as? EditorViewController }.first
            guard let opened, let tutorial = try TutorialLibrary.bundled().tutorial(id: pending.id)
            else {
                offer = nil
                render()
                return
            }
            offer = nil
            try TutorialRunner.start(tutorial, in: opened)
        } catch let refusal as TutorialRefusal {
            showOffer(
                id: pending.id, title: pending.title, sentence: sentence, beside: offerEditor,
                message: refusal.sentence)
        } catch {
            showOffer(
                id: pending.id, title: pending.title, sentence: sentence, beside: offerEditor,
                message: error.localizedDescription)
        }
    }

    private func showOffer(
        id: String, title: String, sentence: String, beside: EditorViewController?,
        message: String? = nil
    ) {
        offer = (id, title)
        offerEditor = beside
        spotlight.hide()
        let panel = ensurePanel()
        panel.showOffer(
            title: title, sentence: sentence, message: message ?? Self.offerLine, tutorial: id)
        place(beside: beside)
        panel.window?.orderFront(nil)
    }

    // MARK: - Serving

    private func runnerChanged(_ runner: TutorialRunner) {
        guard let changed = runner.editor else { return }
        if changed !== editor {
            // A stale runner of another window (an exit there) changes nothing.
            guard changed.tutorialRunner === runner else { return }
            let previous = editor
            serve(changed)
            previous?.tutorialRunner?.exit()
        }
        if changed.tutorialRunner === runner { offer = nil }
        render()
    }

    /// The served window's step in the panel and its target in the ring, or
    /// both hidden once no tutorial runs there.
    private func render() {
        if offer != nil { return }
        guard let editor, let runner = editor.tutorialRunner,
              let window = editor.view.window, !window.isMiniaturized
        else {
            hideAll()
            if editor?.tutorialRunner == nil { unserve() }
            return
        }
        let panel = ensurePanel()
        panel.showStep(runner)
        place(beside: editor)
        panel.window?.orderFront(nil)
        let step = (
            runner: ObjectIdentifier(runner), index: runner.index, finished: runner.finished
        )
        let changed = lastStep.map { $0 != step } ?? true
        lastStep = step
        spotlight.show(
            runner.finished ? nil : runner.currentStep.spotlight, in: editor,
            created: runner.created, stepChanged: changed)
    }

    private func hideAll() {
        panel?.window?.orderOut(nil)
        spotlight.hide()
        lastStep = nil
    }

    private func serve(_ next: EditorViewController) {
        unserve()
        editor = next
        guard let window = next.view.window else { return }
        let center = NotificationCenter.default
        windowObservers.append(
            center.addObserver(
                forName: NSWindow.willCloseNotification, object: window, queue: nil
            ) { [weak self] _ in self?.servedWindowWillClose() })
        for name in [NSWindow.didMoveNotification, NSWindow.didResizeNotification] {
            windowObservers.append(
                center.addObserver(forName: name, object: window, queue: nil) { [weak self] _ in
                    guard let self, self.panel?.window?.isVisible == true else { return }
                    self.place(beside: self.offer == nil ? self.editor : self.offerEditor)
                })
        }
        for name in [NSWindow.didMiniaturizeNotification, NSWindow.didDeminiaturizeNotification] {
            windowObservers.append(
                center.addObserver(forName: name, object: window, queue: nil) { [weak self] _ in
                    self?.render()
                })
        }
    }

    private func unserve() {
        for observer in windowObservers { NotificationCenter.default.removeObserver(observer) }
        windowObservers = []
        editor = nil
    }

    /// Closing the window or the project ends the tutorial.
    private func servedWindowWillClose() {
        let closing = editor
        unserve()
        closing?.tutorialRunner?.exit()
        closing?.tutorialRunner = nil
        if offer == nil || offerEditor === closing { offer = nil }
        hideAll()
    }

    private func ensurePanel() -> TutorialPanelController {
        if let panel { return panel }
        let made = TutorialPanelController()
        made.onPress = { [weak self] button in self?.press(button) }
        made.projectPath = { [weak self] in
            guard let document = self?.editor?.document else { return nil }
            return AgentServer.path(of: document)
        }
        panel = made
        return made
    }

    // MARK: - Placement

    /// Beside `editor`'s window by `panelOrigin`, or centred on the main
    /// screen with no window.
    private func place(beside editor: EditorViewController?) {
        guard let window = panel?.window else { return }
        let size = window.frame.size
        if let editorWindow = editor?.view.window,
           let screen = (editorWindow.screen ?? NSScreen.main)?.visibleFrame
        {
            window.setFrameOrigin(
                Self.panelOrigin(editor: editorWindow.frame, panel: size, screen: screen))
        } else if let screen = (NSScreen.main ?? NSScreen.screens.first)?.visibleFrame {
            window.setFrameOrigin(
                NSPoint(x: screen.midX - size.width / 2, y: screen.midY - size.height / 2))
        }
    }

    /// Right of the editor window by 12 pt with the tops aligned when that
    /// fits `screen`; else left of it; else inside its bottom-left corner,
    /// 16 pt in.
    static func panelOrigin(editor: NSRect, panel: NSSize, screen: NSRect) -> NSPoint {
        let top = editor.maxY - panel.height
        let right = NSRect(
            origin: NSPoint(x: editor.maxX + besideGap, y: top), size: panel)
        if screen.contains(right) { return right.origin }
        let left = NSRect(
            origin: NSPoint(x: editor.minX - besideGap - panel.width, y: top), size: panel)
        if screen.contains(left) { return left.origin }
        return NSPoint(x: editor.minX + cornerInset, y: editor.minY + cornerInset)
    }

    // MARK: - Helpers

    /// The guide's title with its first character uppercased, the rest as
    /// written ("Change a clip's volume").
    static func displayTitle(_ title: String) -> String {
        title.prefix(1).uppercased() + title.dropFirst()
    }

    /// The main window's editor, else the first editor in window order — a
    /// shown window with a project, never one left over from a close.
    static func frontEditor() -> EditorViewController? {
        func serving(_ window: NSWindow?) -> EditorViewController? {
            guard let window, window.isVisible,
                  let editor = window.contentViewController as? EditorViewController,
                  editor.document != nil
            else { return nil }
            return editor
        }
        if let main = serving(NSApp.mainWindow) { return main }
        return NSApp.orderedWindows.lazy.compactMap { serving($0) }.first
    }
}

import AppKit

/// A coach panel button; the raw value is its id in `tutorial_press` and the
/// panel's state, and `tutorial.<raw>` its accessibility id.
enum TutorialPanelButton: String, CaseIterable {
    case back, showMe = "show_me", skip, next, exit, openPractice = "open_practice", close

    var title: String {
        switch self {
        case .back: return "Back"
        case .showMe: return "Show Me"
        case .skip: return "Skip"
        case .next: return "Next"
        case .exit: return "Exit"
        case .openPractice: return "Open Practice Project"
        case .close: return "Close"
        }
    }
}

/// The coach panel's window (spec §11 TU-4, TU-10 (4)): never key, never main,
/// so typing stays in the editor's field and a click on a button acts with
/// the editor still key.
final class TutorialPanel: NSPanel {
    override var canBecomeKey: Bool { false }
    override var canBecomeMain: Bool { false }
}

/// The coach panel (spec §11 TU-10 (4)): a view over the runner's state —
/// the title, "Step n of m" with the tick, the step's sentence with its bold
/// and code spans, a muted message, and the buttons the runner offers — or
/// the finish, or an offer of the practice project. It decides nothing: a
/// press goes to `onPress` (the coach). The tick holds a met wait's step for
/// `tickHold` on a main-thread `Timer`, a documented seam, then renders the
/// runner, which it holds only weakly. Main only.
final class TutorialPanelController: NSWindowController {
    static let tickHold: TimeInterval = 0.8
    static let cardWidth: CGFloat = 320
    private static let inset: CGFloat = 16

    var onPress: ((TutorialPanelButton) -> Void)?
    /// The served editor's project path for the state, set by the coach.
    var projectPath: (() -> String?)?

    private let titleLabel = NSTextField(wrappingLabelWithString: "")
    private let progressLabel = NSTextField(labelWithString: "")
    private let tickView = NSImageView()
    private let textLabel = NSTextField(wrappingLabelWithString: "")
    private let messageLabel = NSTextField(wrappingLabelWithString: "")
    private let buttonRow = NSStackView()
    private let card = NSStackView()
    private var buttons: [TutorialPanelButton: StickerButton] = [:]
    private var shown: [TutorialPanelButton] = []

    private var mode = "step"
    private var tutorialID: String?
    private var plainText = ""
    private var message: String?
    private var ticking = false
    private var tickTimer: Timer?
    private weak var runner: TutorialRunner?
    /// The runner and its `lastCompleted` the panel last saw, so only a NEW
    /// step left by its wait ticks.
    private var seen: (runner: ObjectIdentifier, step: Int, by: TutorialAdvance)?

    init() {
        let panel = TutorialPanel(
            contentRect: NSRect(x: 0, y: 0, width: Self.cardWidth, height: 160),
            styleMask: [.titled, .nonactivatingPanel, .utilityWindow], backing: .buffered,
            defer: false)
        panel.title = "Tutorial"
        panel.level = .floating
        panel.hidesOnDeactivate = false
        panel.becomesKeyOnlyIfNeeded = true
        panel.isReleasedWhenClosed = false
        panel.isExcludedFromWindowsMenu = true
        panel.backgroundColor = DS.chromeBackground
        super.init(window: panel)
        build(in: panel)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TutorialPanelController does not support NSCoder")
    }

    // MARK: - Layout

    private func build(in panel: NSPanel) {
        let width = Self.cardWidth - 2 * Self.inset
        for (label, id) in [
            (titleLabel, "tutorial.title"), (progressLabel, "tutorial.progress"),
            (textLabel, "tutorial.text"), (messageLabel, "tutorial.message"),
        ] {
            label.isSelectable = false
            label.isEditable = false
            label.setAccessibilityIdentifier(id)
        }
        for label in [titleLabel, textLabel, messageLabel] {
            label.preferredMaxLayoutWidth = width
        }
        titleLabel.font = DS.sans(14, weight: .semibold)
        titleLabel.textColor = DS.textStrong
        progressLabel.font = DS.sans(11)
        progressLabel.textColor = DS.textMuted
        messageLabel.font = DS.sans(12)
        messageLabel.textColor = DS.textMuted
        tickView.image = NSImage(
            systemSymbolName: "checkmark.circle.fill", accessibilityDescription: "Done")
        tickView.contentTintColor = DS.accent
        tickView.setAccessibilityIdentifier("tutorial.tick")
        tickView.isHidden = true

        let progress = NSStackView(views: [progressLabel, tickView])
        progress.orientation = .horizontal
        progress.spacing = 4
        // A row in the leading-aligned card hugs its content, or its width is
        // ambiguous (an NSStackView's hugging is `setHuggingPriority`).
        progress.setHuggingPriority(.defaultHigh, for: .horizontal)

        buttonRow.orientation = .horizontal
        buttonRow.spacing = 6
        buttonRow.setHuggingPriority(.defaultHigh, for: .horizontal)
        for kind in TutorialPanelButton.allCases {
            let style: StickerButton.Style =
                kind == .showMe || kind == .next || kind == .openPractice ? .primary : .secondary
            let button = StickerButton(
                title: kind.title, style: style, target: self, action: #selector(pressed(_:)))
            button.setAccessibilityIdentifier("tutorial." + kind.rawValue)
            buttons[kind] = button
        }

        card.orientation = .vertical
        card.alignment = .leading
        card.spacing = 8
        card.edgeInsets = NSEdgeInsets(
            top: Self.inset, left: Self.inset, bottom: Self.inset, right: Self.inset)
        for view in [titleLabel, progress, textLabel, messageLabel, buttonRow] as [NSView] {
            card.addArrangedSubview(view)
        }
        for view in [titleLabel, textLabel, messageLabel] as [NSView] {
            view.widthAnchor.constraint(equalToConstant: width).isActive = true
        }
        card.setCustomSpacing(14, after: messageLabel)
        card.translatesAutoresizingMaskIntoConstraints = false
        card.widthAnchor.constraint(equalToConstant: Self.cardWidth).isActive = true

        // The card pinned at the top-left of a plain root, the window sized to
        // its fitting size (the recorder panel's rule).
        let root = NSView()
        root.addSubview(card)
        NSLayoutConstraint.activate([
            card.topAnchor.constraint(equalTo: root.topAnchor),
            card.leadingAnchor.constraint(equalTo: root.leadingAnchor),
        ])
        panel.contentView = root
    }

    @objc private func pressed(_ sender: NSButton) {
        guard let kind = buttons.first(where: { $0.value === sender })?.key else { return }
        onPress?(kind)
    }

    // MARK: - Showing

    /// The runner's state, or — when it just left a step by its met wait —
    /// that step with the tick for `tickHold` first.
    func showStep(_ runner: TutorialRunner) {
        self.runner = runner
        let id = ObjectIdentifier(runner)
        let last = runner.lastCompleted
        let before = seen
        seen = last.map { (id, $0.step, $0.by) }
        if let last, last.by == .wait,
           before?.runner != id || before?.step != last.step || before?.by != last.by
        {
            showTick(runner, step: last.step)
            return
        }
        if before?.runner != id { cancelTick() }
        if ticking { return }
        render(runner)
    }

    /// An offer: what is missing and the practice project (spec §11 TU-5,
    /// TU-10 (2)).
    func showOffer(title: String, sentence: String, message: String?, tutorial: String? = nil) {
        cancelTick()
        runner = nil
        seen = nil
        mode = "offer"
        tutorialID = tutorial
        titleLabel.stringValue = title
        progressLabel.stringValue = ""
        progressLabel.isHidden = true
        setText(sentence)
        setMessage(message)
        setButtons([.openPractice, .close], enabled: [.openPractice, .close])
        fit()
    }

    private func render(_ runner: TutorialRunner) {
        let tutorial = runner.tutorial
        tutorialID = tutorial.id
        titleLabel.stringValue = TutorialCoach.displayTitle(tutorial.title)
        progressLabel.isHidden = false
        tickView.isHidden = true
        buttons[.exit]?.title = runner.finished ? "Done" : TutorialPanelButton.exit.title
        if runner.finished {
            mode = "finished"
            progressLabel.stringValue = "Finished"
            setText("You finished this tutorial.")
            setMessage(Self.message(runner))
            setButtons([.back, .exit], enabled: [.back, .exit])
        } else {
            mode = "step"
            progressLabel.stringValue = "Step \(runner.index + 1) of \(tutorial.steps.count)"
            setText(runner.currentStep.text)
            setMessage(Self.message(runner))
            let offered = runner.offers.compactMap(TutorialPanelButton.init(rawValue:))
            setButtons(offered, enabled: runner.showMeRunning ? [.exit] : Set(offered))
        }
        fit()
    }

    private func showTick(_ runner: TutorialRunner, step: Int) {
        let tutorial = runner.tutorial
        guard step >= 1, step <= tutorial.steps.count else {
            render(runner)
            return
        }
        cancelTick()
        ticking = true
        mode = "step"
        tutorialID = tutorial.id
        titleLabel.stringValue = TutorialCoach.displayTitle(tutorial.title)
        progressLabel.isHidden = false
        progressLabel.stringValue = "Step \(step) of \(tutorial.steps.count)"
        tickView.isHidden = false
        setText(tutorial.steps[step - 1].text)
        setButtons(shown, enabled: [])
        fit()
        tickTimer = Timer.scheduledTimer(withTimeInterval: Self.tickHold, repeats: false) {
            [weak self] _ in
            guard let self else { return }
            self.ticking = false
            self.tickTimer = nil
            if let runner = self.runner { self.render(runner) }
        }
    }

    private func cancelTick() {
        tickTimer?.invalidate()
        tickTimer = nil
        ticking = false
    }

    /// The first that holds: the last Show Me's error on its own step, where
    /// a Show Me export was sent, the reveal's refusal.
    private static func message(_ runner: TutorialRunner) -> String? {
        if let last = runner.lastShowMe, let error = last.error, !runner.finished,
           last.step == runner.index + 1
        {
            return error
        }
        if let path = runner.lastShowMe?.paths.last {
            return "Show Me exports to \((path as NSString).abbreviatingWithTildeInPath)."
        }
        return runner.revealRefused
    }

    private func setText(_ text: String) {
        plainText = TutorialSentence.plain(text)
        textLabel.attributedStringValue = TutorialSentence.attributed(
            text, font: DS.sans(13), boldFont: DS.sans(13, weight: .semibold),
            codeFont: DS.mono(12), color: DS.textStrong)
    }

    private func setMessage(_ text: String?) {
        message = text
        messageLabel.stringValue = text ?? ""
        messageLabel.isHidden = text == nil
    }

    private func setButtons(_ list: [TutorialPanelButton], enabled: Set<TutorialPanelButton>) {
        shown = list
        for view in buttonRow.arrangedSubviews { buttonRow.removeArrangedSubview(view) }
        for view in buttonRow.subviews { view.removeFromSuperview() }
        for kind in list {
            guard let button = buttons[kind] else { continue }
            button.isEnabled = enabled.contains(kind)
            buttonRow.addArrangedSubview(button)
        }
    }

    /// Sized to the card, keeping the top-left (the recorder panel's rule).
    private func fit() {
        guard let window else { return }
        card.layoutSubtreeIfNeeded()
        let size = card.fittingSize
        var frame = window.frameRect(forContentRect: NSRect(origin: .zero, size: size))
        let current = window.frame
        frame.origin = NSPoint(x: current.minX, y: current.maxY - frame.height)
        window.setFrame(frame, display: window.isVisible)
    }

    // MARK: - The dev tools' reads

    /// `tutorial_state`'s and `tutorial_press`'s `panel`.
    func state() -> [String: Any] {
        [
            "shown": window?.isVisible ?? false,
            "mode": mode,
            "tutorial": tutorialID.map { $0 as Any } ?? NSNull(),
            "title": titleLabel.stringValue,
            "progress": progressLabel.isHidden ? "" : progressLabel.stringValue,
            "text": plainText,
            "message": message.map { $0 as Any } ?? NSNull(),
            "buttons": shown.map(\.rawValue),
            "enabled": shown.filter { buttons[$0]?.isEnabled == true }.map(\.rawValue),
            "tick": ticking,
            "project": projectPath?().map { $0 as Any } ?? NSNull(),
        ]
    }

    /// The button, when it is shown and enabled.
    func button(_ b: TutorialPanelButton) -> NSButton? {
        guard shown.contains(b), let button = buttons[b], button.isEnabled else { return nil }
        return button
    }
}

