1	import AppKit
2	
3	/// The spotlight's ring (spec §11 TU-11 (3)): a 2 pt accent square stroke
4	/// drawn inside its bounds, which sit 4 pt outside the target. Passive:
5	/// `hitTest` answers nil. `snapshot_ui` stages a fresh one at the live ring's
6	/// frame, so a capture shows it and its layout dump holds `identifier`.
7	final class TutorialRingView: NSView {
8	    static let identifier = "tutorial.spotlight"
9	    static let outset: CGFloat = 4
10	    static let lineWidth: CGFloat = 2
11	
12	    override init(frame: NSRect) {
13	        super.init(frame: frame)
14	        setAccessibilityIdentifier(Self.identifier)
15	    }
16	
17	    @available(*, unavailable)
18	    required init?(coder: NSCoder) {
19	        fatalError("TutorialRingView does not support NSCoder")
20	    }
21	
22	    override func hitTest(_ point: NSPoint) -> NSView? { nil }
23	
24	    override func draw(_ dirtyRect: NSRect) {
25	        let path = NSBezierPath(
26	            rect: bounds.insetBy(dx: Self.lineWidth / 2, dy: Self.lineWidth / 2))
27	        path.lineWidth = Self.lineWidth
28	        DS.accent.setStroke()
29	        path.stroke()
30	    }
31	
32	    /// `target` outset by 4 and intersected with `bounds` (the spotlight
33	    /// window's content bounds), so a side at the window's edge still draws
34	    /// its stroke, over the target's edge.
35	    static func frame(for target: NSRect, in bounds: NSRect) -> NSRect {
36	        target.insetBy(dx: -outset, dy: -outset).intersection(bounds)
37	    }
38	}
39	
40	/// A borderless, clear, shadowless, click-through window that never takes key
41	/// or main: the ring's host, a child above the window holding the target.
42	final class TutorialSpotlightWindow: NSWindow {
43	    init() {
44	        super.init(
45	            contentRect: NSRect(x: 0, y: 0, width: 10, height: 10), styleMask: [.borderless],
46	            backing: .buffered, defer: true)
47	        isOpaque = false
48	        backgroundColor = .clear
49	        hasShadow = false
50	        ignoresMouseEvents = true
51	        isReleasedWhenClosed = false
52	        isExcludedFromWindowsMenu = true
53	        contentView = TutorialSpotlightRoot()
54	    }
55	
56	    override var canBecomeKey: Bool { false }
57	    override var canBecomeMain: Bool { false }
58	}
59	
60	/// The spotlight window's root: flipped, so a ring is placed by its top-left.
61	private final class TutorialSpotlightRoot: NSView {
62	    override var isFlipped: Bool { true }
63	    override func hitTest(_ point: NSPoint) -> NSView? { nil }
64	}
65	
66	/// The ring over the served editor (spec §11 TU-11): the target resolved by
67	/// `TutorialTargetResolver`, the window made a child of the window holding it
68	/// (the editor's, or its attached sheet's), and re-resolved on one coalesced
69	/// main turn after any layout change while a target is shown — a documented
70	/// `DispatchQueue.main.async` seam. A target with no rect hides the ring;
71	/// nothing is ever drawn at a guessed place. Main only; it holds the editor
72	/// weakly and has no `deinit` work.
73	final class TutorialSpotlight {
74	    private(set) var target: String?
75	    private(set) var spot: TutorialTargetSpot?
76	    private weak var editor: EditorViewController?
77	    private var created: [UInt32] = []
78	    private let window = TutorialSpotlightWindow()
79	    private let ring = TutorialRingView(frame: .zero)
80	    /// The window the spotlight is a child of while the ring shows.
81	    private weak var parent: NSWindow?
82	    /// The ring's frame in `parent`'s content view, while it shows.
83	    private var shownFrame: NSRect?
84	    private var observers: [NSObjectProtocol] = []
85	    private weak var observedWindow: NSWindow?
86	    private var refreshPending = false
87	
88	    init() {
89	        window.contentView?.addSubview(ring)
90	    }
91	
92	    /// Shows the ring on `target` in `editor`'s window (nil hides it). A new
93	    /// step first brings a clip target into view.
94	    func show(
95	        _ target: String?, in editor: EditorViewController, created: [UInt32], stepChanged: Bool
96	    ) {
97	        guard let target else {
98	            hide()
99	            return
100	        }
101	        self.target = target
102	        self.editor = editor
103	        self.created = created
104	        if stepChanged {
105	            TutorialTargetResolver.bringIntoView(target, in: editor, created: created)
106	        }
107	        observe(editor)
108	        refresh()
109	    }
110	
111	    /// No target: the ring out and every observer removed.
112	    func hide() {
113	        target = nil
114	        spot = nil
115	        removeObservers()
116	        orderOut()
117	    }
118	
119	    /// One re-resolve on the next main turn, however many ask before it.
120	    func refreshSoon() {
121	        guard target != nil, !refreshPending else { return }
122	        refreshPending = true
123	        DispatchQueue.main.async { [weak self] in
124	            guard let self else { return }
125	            self.refreshPending = false
126	            self.refresh()
127	        }
128	    }
129	
130	    /// The ring view's frame in `window.contentView`'s coordinates, when the
131	    /// ring shows over that window.
132	    func ringFrame(in window: NSWindow) -> NSRect? {
133	        guard self.window.isVisible, parent === window else { return nil }
134	        return shownFrame
135	    }
136	
137	    // MARK: - Resolving
138	
139	    private func refresh() {
140	        guard let target, let editor else {
141	            hide()
142	            return
143	        }
144	        let created = editor.tutorialRunner?.created ?? self.created
145	        let resolved = TutorialTargetResolver.resolve(target, in: editor, created: created)
146	        spot = resolved
147	        guard let rect = resolved.rect, let holder = resolved.window, holder.isVisible,
148	              !holder.isMiniaturized, let content = holder.contentView
149	        else {
150	            orderOut()
151	            return
152	        }
153	        if parent !== holder {
154	            parent?.removeChildWindow(window)
155	            holder.addChildWindow(window, ordered: .above)
156	            parent = holder
157	        }
158	        let screenFrame = holder.convertToScreen(content.convert(content.bounds, to: nil))
159	        window.setFrame(screenFrame, display: false)
160	        let frame = TutorialRingView.frame(for: rect, in: content.bounds)
161	        shownFrame = frame
162	        let top = content.isFlipped ? frame.minY : content.bounds.height - frame.maxY
163	        ring.frame = NSRect(x: frame.minX, y: top, width: frame.width, height: frame.height)
164	        ring.needsDisplay = true
165	        if !window.isVisible { window.orderFront(nil) }
166	    }
167	
168	    private func orderOut() {
169	        shownFrame = nil
170	        parent?.removeChildWindow(window)
171	        parent = nil
172	        window.orderOut(nil)
173	    }
174	
175	    // MARK: - Following layout
176	
177	    /// Any view frame or bounds change in the editor window or its sheet, the
178	    /// window's resize and sheets, the served document's changes and the
179	    /// runner's posts each ask for one refresh. Registered once per editor
180	    /// window while a target is shown.
181	    private func observe(_ editor: EditorViewController) {
182	        guard let editorWindow = editor.view.window else { return }
183	        if observedWindow === editorWindow, !observers.isEmpty { return }
184	        removeObservers()
185	        observedWindow = editorWindow
186	        let center = NotificationCenter.default
187	        for name in [NSView.frameDidChangeNotification, NSView.boundsDidChangeNotification] {
188	            observers.append(
189	                center.addObserver(forName: name, object: nil, queue: nil) { [weak self] note in
190	                    self?.viewChanged(note.object as? NSView)
191	                })
192	        }
193	        for name in [
194	            NSWindow.didResizeNotification, NSWindow.willBeginSheetNotification,
195	            NSWindow.didEndSheetNotification,
196	        ] {
197	            observers.append(
198	                center.addObserver(forName: name, object: editorWindow, queue: nil) {
199	                    [weak self] _ in self?.refreshSoon()
200	                })
201	        }
202	        observers.append(
203	            center.addObserver(
204	                forName: .projectDocumentDidChange, object: editor.document,
205	                queue: nil
206	            ) { [weak self] _ in self?.refreshSoon() })
207	        observers.append(
208	            center.addObserver(forName: .tutorialRunnerDidChange, object: nil, queue: nil) {
209	                [weak self] _ in self?.refreshSoon()
210	            })
211	    }
212	
213	    /// Kept only for a view in the editor window or its sheet — never the
214	    /// spotlight's own.
215	    private func viewChanged(_ view: NSView?) {
216	        guard let changed = view?.window, changed !== window,
217	              let editorWindow = observedWindow,
218	              changed === editorWindow || changed === editorWindow.attachedSheet
219	        else { return }
220	        refreshSoon()
221	    }
222	
223	    private func removeObservers() {
224	        for observer in observers { NotificationCenter.default.removeObserver(observer) }
225	        observers = []
226	        observedWindow = nil
227	    }
228	}
