import AppKit

/// The spotlight's ring (spec §11 TU-11 (3)): a 2 pt accent square stroke
/// drawn inside its bounds, which sit 4 pt outside the target. Passive:
/// `hitTest` answers nil. `snapshot_ui` stages a fresh one at the live ring's
/// frame, so a capture shows it and its layout dump holds `identifier`.
final class TutorialRingView: NSView {
    static let identifier = "tutorial.spotlight"
    static let outset: CGFloat = 4
    static let lineWidth: CGFloat = 2

    override init(frame: NSRect) {
        super.init(frame: frame)
        setAccessibilityIdentifier(Self.identifier)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TutorialRingView does not support NSCoder")
    }

    override func hitTest(_ point: NSPoint) -> NSView? { nil }

    override func draw(_ dirtyRect: NSRect) {
        let path = NSBezierPath(
            rect: bounds.insetBy(dx: Self.lineWidth / 2, dy: Self.lineWidth / 2))
        path.lineWidth = Self.lineWidth
        DS.accent.setStroke()
        path.stroke()
    }

    /// `target` outset by 4 and intersected with `bounds` (the spotlight
    /// window's content bounds), so a side at the window's edge still draws
    /// its stroke, over the target's edge.
    static func frame(for target: NSRect, in bounds: NSRect) -> NSRect {
        target.insetBy(dx: -outset, dy: -outset).intersection(bounds)
    }
}

/// A borderless, clear, shadowless, click-through window that never takes key
/// or main: the ring's host, a child above the window holding the target.
final class TutorialSpotlightWindow: NSWindow {
    init() {
        super.init(
            contentRect: NSRect(x: 0, y: 0, width: 10, height: 10), styleMask: [.borderless],
            backing: .buffered, defer: true)
        isOpaque = false
        backgroundColor = .clear
        hasShadow = false
        ignoresMouseEvents = true
        isReleasedWhenClosed = false
        isExcludedFromWindowsMenu = true
        contentView = TutorialSpotlightRoot()
    }

    override var canBecomeKey: Bool { false }
    override var canBecomeMain: Bool { false }
}

/// The spotlight window's root: flipped, so a ring is placed by its top-left.
private final class TutorialSpotlightRoot: NSView {
    override var isFlipped: Bool { true }
    override func hitTest(_ point: NSPoint) -> NSView? { nil }
}

/// The ring over the served editor (spec §11 TU-11): the target resolved by
/// `TutorialTargetResolver`, the window made a child of the window holding it
/// (the editor's, or its attached sheet's), and re-resolved on one coalesced
/// main turn after any layout change while a target is shown — a documented
/// `DispatchQueue.main.async` seam. A target with no rect hides the ring;
/// nothing is ever drawn at a guessed place. Main only; it holds the editor
/// weakly and has no `deinit` work.
final class TutorialSpotlight {
    private(set) var target: String?
    private(set) var spot: TutorialTargetSpot?
    private weak var editor: EditorViewController?
    private var created: [UInt32] = []
    private let window = TutorialSpotlightWindow()
    private let ring = TutorialRingView(frame: .zero)
    /// The window the spotlight is a child of while the ring shows.
    private weak var parent: NSWindow?
    /// The ring's frame in `parent`'s content view, while it shows.
    private var shownFrame: NSRect?
    private var observers: [NSObjectProtocol] = []
    private weak var observedWindow: NSWindow?
    private var refreshPending = false

    init() {
        window.contentView?.addSubview(ring)
    }

    /// Shows the ring on `target` in `editor`'s window (nil hides it). A new
    /// step first brings a clip target into view.
    func show(
        _ target: String?, in editor: EditorViewController, created: [UInt32], stepChanged: Bool
    ) {
        guard let target else {
            hide()
            return
        }
        self.target = target
        self.editor = editor
        self.created = created
        if stepChanged {
            TutorialTargetResolver.bringIntoView(target, in: editor, created: created)
        }
        observe(editor)
        refresh()
    }

    /// No target: the ring out and every observer removed.
    func hide() {
        target = nil
        spot = nil
        removeObservers()
        orderOut()
    }

    /// One re-resolve on the next main turn, however many ask before it.
    func refreshSoon() {
        guard target != nil, !refreshPending else { return }
        refreshPending = true
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            self.refreshPending = false
            self.refresh()
        }
    }

    /// The ring view's frame in `window.contentView`'s coordinates, when the
    /// ring shows over that window.
    func ringFrame(in window: NSWindow) -> NSRect? {
        guard self.window.isVisible, parent === window else { return nil }
        return shownFrame
    }

    // MARK: - Resolving

    private func refresh() {
        guard let target, let editor else {
            hide()
            return
        }
        let created = editor.tutorialRunner?.created ?? self.created
        let resolved = TutorialTargetResolver.resolve(target, in: editor, created: created)
        spot = resolved
        guard let rect = resolved.rect, let holder = resolved.window, holder.isVisible,
              !holder.isMiniaturized, let content = holder.contentView
        else {
            orderOut()
            return
        }
        if parent !== holder {
            parent?.removeChildWindow(window)
            holder.addChildWindow(window, ordered: .above)
            parent = holder
        }
        let screenFrame = holder.convertToScreen(content.convert(content.bounds, to: nil))
        window.setFrame(screenFrame, display: false)
        let frame = TutorialRingView.frame(for: rect, in: content.bounds)
        shownFrame = frame
        let top = content.isFlipped ? frame.minY : content.bounds.height - frame.maxY
        ring.frame = NSRect(x: frame.minX, y: top, width: frame.width, height: frame.height)
        ring.needsDisplay = true
        if !window.isVisible { window.orderFront(nil) }
    }

    private func orderOut() {
        shownFrame = nil
        parent?.removeChildWindow(window)
        parent = nil
        window.orderOut(nil)
    }

    // MARK: - Following layout

    /// Any view frame or bounds change in the editor window or its sheet, the
    /// window's resize and sheets, the served document's changes and the
    /// runner's posts each ask for one refresh. Registered once per editor
    /// window while a target is shown.
    private func observe(_ editor: EditorViewController) {
        guard let editorWindow = editor.view.window else { return }
        if observedWindow === editorWindow, !observers.isEmpty { return }
        removeObservers()
        observedWindow = editorWindow
        let center = NotificationCenter.default
        for name in [NSView.frameDidChangeNotification, NSView.boundsDidChangeNotification] {
            observers.append(
                center.addObserver(forName: name, object: nil, queue: nil) { [weak self] note in
                    self?.viewChanged(note.object as? NSView)
                })
        }
        for name in [
            NSWindow.didResizeNotification, NSWindow.willBeginSheetNotification,
            NSWindow.didEndSheetNotification,
        ] {
            observers.append(
                center.addObserver(forName: name, object: editorWindow, queue: nil) {
                    [weak self] _ in self?.refreshSoon()
                })
        }
        observers.append(
            center.addObserver(
                forName: .projectDocumentDidChange, object: editor.document,
                queue: nil
            ) { [weak self] _ in self?.refreshSoon() })
        observers.append(
            center.addObserver(forName: .tutorialRunnerDidChange, object: nil, queue: nil) {
                [weak self] _ in self?.refreshSoon()
            })
    }

    /// Kept only for a view in the editor window or its sheet — never the
    /// spotlight's own.
    private func viewChanged(_ view: NSView?) {
        guard let changed = view?.window, changed !== window,
              let editorWindow = observedWindow,
              changed === editorWindow || changed === editorWindow.attachedSheet
        else { return }
        refreshSoon()
    }

    private func removeObservers() {
        for observer in observers { NotificationCenter.default.removeObserver(observer) }
        observers = []
        observedWindow = nil
    }
}

