60	/// The spotlight window's root: flipped, so a ring is placed by its top-left.
61	private final class TutorialSpotlightRoot: NSView {
62	    override var isFlipped: Bool { true }
63	    override func hitTest(_ point: NSPoint) -> NSView? { nil }
64	}
