3	/// What a spotlight target name means (spec §11 TU-11 (1)).
4	enum TutorialTargetKind: Equatable {
5	    /// A view carrying the name as its accessibility identifier.
6	    case view(String)
7	    case inspectorTab(InspectorTab)
8	    case subTab(ClipSubTab)
9	    case section(String)
10	    case clip(TutorialClipSet)
11	}
12	
13	/// Where a target is now: the window it is in and its visible rect in that
14	/// window's content view (clipped to what shows), or no rect and the
15	/// sentence saying why.
16	struct TutorialTargetSpot {
17	    let window: NSWindow?
18	    let rect: NSRect?
19	    let reason: String?
20	}
21	
22	/// Every name in `TutorialTargets` resolved to a window and a visible rect
23	/// (spec §11 TU-11): a fixed control by its accessibility identifier (under
24	/// the editor window's content view, or its attached sheet's for
25	/// `sheet.export.*`), the inspector's tab strip and the Clip tab's sub-tab
26	/// strip by their own arithmetic, a section by the shown pane, a clip by the
27	/// timeline's layout. A target that is hidden, absent or shows nothing
28	/// answers no rect and one sentence (TU-11 (2)) — never a guessed place.
29	/// `tools/proof/tutorial_probe.swift` holds `kind(of:)` to the whole table,
30	/// so a name that does not resolve fails `tutorial_check.py`. Main only.
31	enum TutorialTargetResolver {
32	    static let sheetPrefix = "sheet.export."
33	    private static let tabPrefix = "inspector.tab."
34	    private static let subTabPrefix = "inspector.sub_tab."
35	
36	    /// nil for a name outside `TutorialTargets`.
37	    static func kind(of name: String) -> TutorialTargetKind? {
38	        if name.hasPrefix(tabPrefix) {
39	            let title = String(name.dropFirst(tabPrefix.count))
40	            return InspectorTab.allCases.first { $0.title.lowercased() == title }
41	                .map { .inspectorTab($0) }
42	        }
43	        if name.hasPrefix(subTabPrefix) {
44	            return ClipSubTab(rawValue: String(name.dropFirst(subTabPrefix.count)))
45	                .map { .subTab($0) }
46	        }
47	        if TutorialTargets.fixed[name] != nil { return .view(name) }
48	        if name.hasPrefix(TutorialTargets.sectionPrefix) {
49	            let id = String(name.dropFirst(TutorialTargets.sectionPrefix.count))
50	            return TutorialTargets.sections[id] != nil ? .section(id) : nil
51	        }
52	        if name.hasPrefix(TutorialTargets.clipPrefix) {
53	            let ref = String(name.dropFirst(TutorialTargets.clipPrefix.count))
54	            return TutorialClipSet(rawValue: ref).map { .clip($0) }
55	        }
56	        return nil
57	    }
58	
59	    static func resolve(
60	        _ name: String, in editor: EditorViewController, created: [UInt32]
61	    ) -> TutorialTargetSpot {
62	        guard let kind = kind(of: name) else {
63	            return TutorialTargetSpot(
64	                window: nil, rect: nil, reason: "No spotlight target is called \(name).")
65	        }
66	        guard editor.isViewLoaded, let window = editor.view.window else {
67	            return TutorialTargetSpot(window: nil, rect: nil, reason: "The editor has no window.")
68	        }
69	        switch kind {
70	        case .view(let id):
71	            return resolveView(id, editor: editor, window: window)
72	        case .inspectorTab(let tab):
73	            guard let strip: PanelTabsView = descendant(of: editor.inspector) else {
74	                return notShown(name, window)
75	            }
76	            let r = InspectorTabBadge.tabRect(
77	                index: tab.rawValue, stripWidth: strip.bounds.width,
78	                stripHeight: strip.bounds.height)
79	            return spot(r, in: strip, window: window, otherwise: notOnScreen(name))
80	        case .subTab(let sub):
81	            let reason = "The Clip tab does not show the \(sub.title) sub-tab now."
82	            guard let strip: ClipSubTabsView = descendant(of: editor.inspector),
83	                  let index = strip.tabs.firstIndex(of: sub)
84	            else { return TutorialTargetSpot(window: window, rect: nil, reason: reason) }
85	            return spot(strip.cellRect(index), in: strip, window: window, otherwise: reason)
86	        case .section(let id):
87	            let reason = "The inspector does not show the \(id) section now."
88	            let sections = editor.inspector?.shownPane()?.1.sections ?? []
89	            guard let section = sections.first(where: { $0.id == id }) else {
90	                return TutorialTargetSpot(window: window, rect: nil, reason: reason)
91	            }
92	            return spot(section.bounds, in: section, window: window, otherwise: reason)
93	        case .clip(let set):
94	            return resolveClip(set, editor: editor, window: window, created: created)
95	        }
96	    }
97	
98	    /// A clip target is scrolled into view (as the rename field's reveal
99	    /// does, both pinned bands allowed for); anything else is left alone —
100	    /// the runner's reveal already scrolled a section.
101	    static func bringIntoView(_ name: String, in editor: EditorViewController, created: [UInt32]) {
102	        guard case .clip(let set)? = kind(of: name), let timeline = editor.timeline,
103	              let rect = clipRect(set, editor: editor, timeline: timeline, created: created)
104	        else { return }
105	        var reveal = rect
106	        reveal.origin.x -= TimelineLayout.headerWidth
107	        reveal.size.width += TimelineLayout.headerWidth
108	        reveal.origin.y -= TimelineLayout.rulerHeight
109	        reveal.size.height += TimelineLayout.rulerHeight
110	        timeline.content.scrollToVisible(reveal)
111	    }
112	
113	    // MARK: - The kinds
114	
115	    private static func resolveView(
116	        _ id: String, editor: EditorViewController, window: NSWindow
117	    ) -> TutorialTargetSpot {
118	        var holder = window
119	        if id.hasPrefix(sheetPrefix) {
120	            guard let sheet = window.attachedSheet else {
121	                return TutorialTargetSpot(
122	                    window: nil, rect: nil, reason: "The export sheet is not open.")
123	            }
124	            holder = sheet
125	        }
126	        guard let root = holder.contentView, let view = firstShown(id, under: root) else {
127	            return notShown(id, holder)
128	        }
129	        if id == "timeline.clips", let timeline = editor.timeline {
130	            let r = laneArea(timeline).intersection(view.bounds)
131	            return spot(r, in: view, window: holder, otherwise: notOnScreen(id))
132	        }
133	        return spot(view.bounds, in: view, window: holder, otherwise: notOnScreen(id))
134	    }
135	
136	    private static func resolveClip(
137	        _ set: TutorialClipSet, editor: EditorViewController, window: NSWindow,
138	        created: [UInt32]
139	    ) -> TutorialTargetSpot {
140	        let none = set == .selection ? "No clip is selected." : "No clip has been made yet."
141	        guard let timeline = editor.timeline else {
142	            return TutorialTargetSpot(window: window, rect: nil, reason: none)
143	        }
144	        guard let r = clipRect(set, editor: editor, timeline: timeline, created: created) else {
145	            return TutorialTargetSpot(window: window, rect: nil, reason: none)
146	        }
147	        return spot(
148	            r.intersection(laneArea(timeline)), in: timeline.content, window: window,
149	            otherwise: "The clip is not on screen now.")
150	    }
151	
152	    /// The clip's bar in the timeline content's coordinates: the earliest of
153	    /// the current selection, or of the runner's `$created`.
154	    private static func clipRect(
155	        _ set: TutorialClipSet, editor: EditorViewController, timeline: TimelineView,
156	        created: [UInt32]
157	    ) -> NSRect? {
158	        let snapshot = timeline.snapshot
159	        let ids: [UInt32]
160	        switch set {
161	        case .selection: ids = Array(editor.document?.selection ?? [])
162	        case .created: ids = created
163	        }
164	        guard let first = TutorialVariables.timeOrdered(ids, in: snapshot).first,
165	              let clip = snapshot.clips.first(where: { $0.id == first }),
166	              let index = snapshot.trackIndex(of: clip.track)
167	        else { return nil }
168	        return timeline.layout.clipRect(clip, row: timeline.layout.row(forTrackIndex: index))
169	    }
170	
171	    /// The clip area as it shows: the content's visible rect less the pinned
172	    /// ruler band (top) and header column (left), which paint over it.
173	    static func laneArea(_ timeline: TimelineView) -> NSRect {
174	        var r = timeline.content.visibleRect
175	        let top = max(r.minY, timeline.ruler.frame.maxY)
176	        let left = max(r.minX, timeline.headers.frame.maxX)
177	        r.size.height = max(0, r.maxY - top)
178	        r.origin.y = top
179	        r.size.width = max(0, r.maxX - left)
180	        r.origin.x = left
181	        return r
182	    }
183	
184	    // MARK: - Helpers
185	
186	    /// `r` (in `view`'s coordinates) cut to what `view` shows and given in
187	    /// the window's content view, or no rect and `otherwise`.
188	    private static func spot(
189	        _ r: NSRect, in view: NSView, window: NSWindow, otherwise: String
190	    ) -> TutorialTargetSpot {
191	        guard let content = window.contentView, view.window === window,
192	              !view.isHiddenOrHasHiddenAncestor
193	        else { return TutorialTargetSpot(window: window, rect: nil, reason: otherwise) }
194	        let visible = r.intersection(view.visibleRect)
195	        guard !visible.isNull, visible.width > 0, visible.height > 0 else {
196	            return TutorialTargetSpot(window: window, rect: nil, reason: otherwise)
197	        }
198	        return TutorialTargetSpot(
199	            window: window, rect: view.convert(visible, to: content), reason: nil)
200	    }
201	
202	    private static func notOnScreen(_ name: String) -> String {
203	        let description = TutorialTargets.fixed[name] ?? "The \(name) control"
204	        return description.prefix(1).uppercased() + description.dropFirst()
205	            + " is not on screen now."
206	    }
207	
208	    private static func notShown(_ name: String, _ window: NSWindow) -> TutorialTargetSpot {
209	        TutorialTargetSpot(window: window, rect: nil, reason: notOnScreen(name))
210	    }
211	
212	    /// The first view under `root`, breadth first, whose identifier is `id`
213	    /// and that is not hidden.
214	    private static func firstShown(_ id: String, under root: NSView) -> NSView? {
215	        var queue: [NSView] = [root]
216	        while !queue.isEmpty {
217	            let view = queue.removeFirst()
218	            if view.accessibilityIdentifier() == id, !view.isHiddenOrHasHiddenAncestor {
219	                return view
220	            }
221	            queue.append(contentsOf: view.subviews)
222	        }
223	        return nil
224	    }
225	
226	    /// The first `T` among the inspector's descendants, breadth first.
227	    private static func descendant<T: NSView>(of inspector: InspectorViewController?) -> T? {
228	        guard let inspector, inspector.isViewLoaded else { return nil }
229	        var queue: [NSView] = [inspector.view]
230	        while !queue.isEmpty {
231	            let view = queue.removeFirst()
232	            if let found = view as? T, !found.isHiddenOrHasHiddenAncestor { return found }
233	            queue.append(contentsOf: view.subviews)
234	        }
235	        return nil
236	    }
237	}
