106	    /// Starts `tutorial` in `editor`'s window, replacing any running there;
107	    /// refused, starting nothing, when its needs are unmet.
108	    @discardableResult
109	    static func start(_ tutorial: Tutorial, in editor: EditorViewController) throws
110	        -> TutorialRunner {
111	        guard let document = editor.document else {
112	            throw TutorialRefusal(sentence: "This window has no project.")
113	        }
114	        if let sentence = TutorialWait.needsSentence(
115	            tutorial.needs, in: document.editedProject.snapshot)
116	        {
117	            throw TutorialRefusal(sentence: sentence)
118	        }
119	        let runner = TutorialRunner(tutorial: tutorial, editor: editor, document: document)
120	        editor.tutorialRunner = runner
121	        runner.observeSheets(editor.view.window)
122	        runner.begin(0, .forward)
123	        return runner
124	    }
