import AppKit

/// A tutorial step's sentence as the coach panel shows it (spec §11 TU-10
/// (4)): the guide's `**bold**` and `` `code` `` spans rendered and their
/// markers dropped, nothing else of Markdown. A marker with no partner after
/// it stays literal. `plain` is the same text with no attributes — what the
/// panel's state answers and `tutorial_chrome_proof.py` re-implements.
enum TutorialSentence {
    private enum Span {
        case text(String), bold(String), code(String)
    }

    static func attributed(
        _ text: String, font: NSFont, boldFont: NSFont, codeFont: NSFont, color: NSColor
    ) -> NSAttributedString {
        let out = NSMutableAttributedString()
        for span in spans(text) {
            let (string, face): (String, NSFont)
            switch span {
            case .text(let s): (string, face) = (s, font)
            case .bold(let s): (string, face) = (s, boldFont)
            case .code(let s): (string, face) = (s, codeFont)
            }
            let attributes: [NSAttributedString.Key: Any] = [.font: face, .foregroundColor: color]
            out.append(NSAttributedString(string: string, attributes: attributes))
        }
        return out
    }

    static func plain(_ text: String) -> String {
        spans(text).map { span -> String in
            switch span {
            case .text(let s), .bold(let s), .code(let s): return s
            }
        }.joined()
    }

    /// Left to right: at a `` ` `` the span runs to the next `` ` ``; at a
    /// `**` to the next `**`; an unpaired marker is text.
    private static func spans(_ text: String) -> [Span] {
        var out: [Span] = []
        var plain = ""
        var rest = Substring(text)
        func flush() {
            if !plain.isEmpty { out.append(.text(plain)) }
            plain = ""
        }
        while let first = rest.first {
            if first == "`", let close = rest.dropFirst().firstIndex(of: "`") {
                flush()
                out.append(.code(String(rest[rest.index(after: rest.startIndex)..<close])))
                rest = rest[rest.index(after: close)...]
                continue
            }
            if rest.hasPrefix("**"), let close = rest.dropFirst(2).range(of: "**") {
                flush()
                let open = rest.index(rest.startIndex, offsetBy: 2)
                out.append(.bold(String(rest[open..<close.lowerBound])))
                rest = rest[close.upperBound...]
                continue
            }
            plain.append(first)
            rest = rest.dropFirst()
        }
        flush()
        return out
    }
}

class Dump:
    """A `snapshot_ui` layout dump: views by index, and frames in its root."""

    def __init__(self, result):
        self.result = result
        self.views = json.loads(Path(result["layout_path"]).read_text())["views"]
        self.size = result["points"]

    def shown(self, vid):
        return [v for v in self.views if v["id"] == vid and not v["hidden"]]

    def by_class(self, name):
        return [v for v in self.views if v["class"] == name and not v["hidden"]]

    def clipped(self, view, rect=None):
        """`rect` (default the view's frame) cut by every ancestor clip view."""
        r = list(rect or view["frame"])
        parent = view["parent"]
        while parent is not None and 0 <= parent < len(self.views):
            above = self.views[parent]
            if above["class"] in CLIP_VIEWS:
                r = intersect(r, above["frame"])
                if r is None:
                    return None
            if above["parent"] == parent:
                break
            parent = above["parent"]
        return r

    def expected(self, name):
        """The expected visible rect of a view target, or None."""
        found = self.shown(name)
        if not found:
            return None
        rect = self.clipped(found[0])
